/**
 * A chart drawn with a pen, not generated by a charting library.
 * Every bar is an uneven four-sided path with a second sketch stroke over it.
 */
export type DoodleBar = {
  label: string;
  value: number;
  display: string;
  color?: string;
};

export default function DoodleChart({
  bars,
  caption,
  className = '',
}: {
  bars: DoodleBar[];
  caption?: string;
  className?: string;
}) {
  const max = Math.max(...bars.map((b) => b.value), 1);
  const baseY = 196;
  const step = 560 / (bars.length + 1);

  return (
    <figure className={className}>
      <svg
        viewBox="0 0 560 250"
        fill="none"
        stroke="currentColor"
        strokeWidth="2.2"
        strokeLinecap="round"
        strokeLinejoin="round"
        className="w-full text-ink"
        aria-label={bars.map((b) => `${b.label}: ${b.display}`).join('; ')}
        role="img"
      >
        {/* faint hand-ruled grid */}
        {[46, 96, 146].map((y, i) => (
          <path
            key={y}
            d={`M34 ${y}c84-${2 + i} 169-${1 + i} 254 0s169 2 238 ${i === 1 ? -1 : 1}`}
            stroke="currentColor"
            strokeOpacity="0.22"
            strokeDasharray="4 9"
          />
        ))}

        {/* the baseline */}
        <path d="M30 197c92-3 184-4 276-1s168 3 224-.4" strokeWidth="2.8" />
        <path d="M32 200c92-2 184-2 276-.5" strokeWidth="1.3" strokeOpacity="0.5" />

        {bars.map((b, i) => {
          const x = step * (i + 1) - 48;
          const w = 96;
          const h = Math.max(4, (b.value / max) * 138);
          const y = baseY - h;
          const stroke = b.color ?? 'currentColor';
          return (
            <g key={b.label} stroke={stroke}>
              {/* the bar, drawn in two passes like a marker sketch */}
              <path
                d={`M${x + 2} ${y + 3} L${x + w - 4} ${y - 1} L${x + w + 2} ${baseY - 4} L${x - 2} ${baseY + 2} Z`}
                fill="currentColor"
                fillOpacity="0.045"
              />
              <path
                d={`M${x + 4} ${y + 5} L${x + w - 6} ${y + 1} L${x + w - 1} ${baseY - 6}`}
                strokeWidth="1.1"
                strokeOpacity="0.55"
              />
              {/* a few hatch marks, not a fill */}
              {[0.35, 0.62, 0.86].map((f) => (
                <path
                  key={f}
                  d={`M${x + 12} ${y + h * f} l${w - 26} ${-3 - f * 2}`}
                  strokeWidth="1"
                  strokeOpacity="0.3"
                />
              ))}
              <text
                x={x + w / 2}
                y={y - 12}
                textAnchor="middle"
                fontFamily="Caveat, cursive"
                fontSize="34"
                fontWeight="600"
                stroke="none"
                fill={stroke}
              >
                {b.display}
              </text>
              <text
                x={x + w / 2}
                y={baseY + 34}
                textAnchor="middle"
                fontFamily="Caveat, cursive"
                fontSize="23"
                stroke="none"
                fill="currentColor"
              >
                {b.label}
              </text>
            </g>
          );
        })}
      </svg>
      {caption && (
        <figcaption className="margin-note mt-1 text-[19px] text-pencil">{caption}</figcaption>
      )}
    </figure>
  );
}
